fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy_tree(root:&Path,dir:&Path,out:&Path){for e in fs::read_dir(dir).unwrap(){let e=e.unwrap();let p=e.path();let name=e.file_name().to_string_lossy().to_string();let kind=e.file_type().unwrap();if kind.is_dir(){if name=="source"||name.starts_with("target-")||["frozen","profiles"].contains(&name.as_str()){continue}copy_tree(root,&p,out);}else if kind.is_file()&&["rs","md","json","jsonl","log","txt"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or("")){let dest=out.join(p.strip_prefix(root).unwrap());fs::create_dir_all(dest.parent().unwrap()).unwrap();fs::copy(p,dest).unwrap();}}}
fn inventory(root:&Path,dir:&Path,out:&mut BTreeMap<String,String>){for e in fs::read_dir(dir).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir(){inventory(root,&p,out)}else{assert!(e.file_type().unwrap().is_file());let rel=p.strip_prefix(root).unwrap().display().to_string();if rel!="SHA256SUMS"{out.insert(rel,hash(p));}}}}
